def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [list(r) for r in grid]

    structure = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val not in (0, 7, 5, 8, 9):
                structure.append((r, c))

    if len(structure) < 2:
        return result

    r1, c1 = structure[0]
    r2, c2 = structure[1]

    if (r2 - r1) == (c2 - c1):
        # SE structure → SW perpendicular  
        perp_const = r1 + c1
        for r in range(rows):
            c = perp_const - r
            if 0 <= c < cols:
                result[r][c] = 3
    else:
        # SW structure → SE perpendicular
        perp_const = r1 - c1
        for r in range(rows):
            c = r - perp_const
            if 0 <= c < cols:
                result[r][c] = 3

    return result
